const triggerOutcome = `-- name: TriggerOutcome :one
UPDATE agent_triggers
SET consecutive_failures = $1, backoff_until = $2,
    paused = paused OR $3::boolean,
    paused_reason = CASE WHEN $3::boolean AND NOT paused THEN 'failures' ELSE paused_reason END
WHERE id = $4
RETURNING id, agent_id, kind, name, source, paused, paused_reason, thread_id, message_template, cron, timezone, missed_policy, next_fire_at, hook_id, webhook_secret_enc, webhook_secret_prefix, filter_path, filter_equals, callback_url, callback_secret_enc, callback_secret_prefix, daily_budget_usd, consecutive_failures, backoff_until, last_fired_at, created_by, created_at, updated_at, revision, once, origin_thread_id
`

type TriggerOutcomeParams struct {
	ConsecutiveFailures int32
	BackoffUntil        *time.Time
	Pause               bool
	ID                  uuid.UUID
}

// A run of the trigger ended: failures in a row, back-off, and an automatic
// pause (paused_reason failures) at the limit. Not a person's change: the
// revision stays.
func (q *Queries) TriggerOutcome(ctx context.Context, arg TriggerOutcomeParams) (AgentTrigger, error) {
	row := q.db.QueryRow(ctx, triggerOutcome,
		arg.ConsecutiveFailures,
		arg.BackoffUntil,
		arg.Pause,
		arg.ID,
	)
	var i AgentTrigger
	err := row.Scan(
		&i.ID,
		&i.AgentID,
		&i.Kind,
		&i.Name,
		&i.Source,
		&i.Paused,
		&i.PausedReason,
		&i.ThreadID,
		&i.MessageTemplate,
		&i.Cron,
		&i.Timezone,
		&i.MissedPolicy,
		&i.NextFireAt,
		&i.HookID,
		&i.WebhookSecretEnc,
		&i.WebhookSecretPrefix,
		&i.FilterPath,
		&i.FilterEquals,
		&i.CallbackUrl,
		&i.CallbackSecretEnc,
		&i.CallbackSecretPrefix,
		&i.DailyBudgetUsd,
		&i.ConsecutiveFailures,
		&i.BackoffUntil,
		&i.LastFiredAt,
		&i.CreatedBy,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.Revision,
		&i.Once,
		&i.OriginThreadID,
	)
	return i, err
}

