const upsertTriggerSettings = `-- name: UpsertTriggerSettings :one
INSERT INTO agent_trigger_settings AS s (agent_id, paused, max_concurrent_runs, max_run_seconds, daily_budget_usd, revision, updated_at)
VALUES ($1, $2, $3, $4,
        $5, 2, $6::timestamptz)
ON CONFLICT (agent_id) DO UPDATE SET paused = EXCLUDED.paused, max_concurrent_runs = EXCLUDED.max_concurrent_runs,
    max_run_seconds = EXCLUDED.max_run_seconds, daily_budget_usd = EXCLUDED.daily_budget_usd,
    revision = s.revision + 1, updated_at = EXCLUDED.updated_at
WHERE s.revision = $7
RETURNING agent_id, paused, max_concurrent_runs, max_run_seconds, daily_budget_usd, revision, updated_at
`

type UpsertTriggerSettingsParams struct {
	AgentID           uuid.UUID
	Paused            bool
	MaxConcurrentRuns *int32
	MaxRunSeconds     *int32
	DailyBudgetUsd    pgtype.Float8
	Now               time.Time
	ExpectedRevision  int64
}

// expected_revision: the revision the caller loaded (the row's, when it has one).
// A new row starts at revision 2: the defaults it replaces were revision 1.
func (q *Queries) UpsertTriggerSettings(ctx context.Context, arg UpsertTriggerSettingsParams) (AgentTriggerSetting, error) {
	row := q.db.QueryRow(ctx, upsertTriggerSettings,
		arg.AgentID,
		arg.Paused,
		arg.MaxConcurrentRuns,
		arg.MaxRunSeconds,
		arg.DailyBudgetUsd,
		arg.Now,
		arg.ExpectedRevision,
	)
	var i AgentTriggerSetting
	err := row.Scan(
		&i.AgentID,
		&i.Paused,
		&i.MaxConcurrentRuns,
		&i.MaxRunSeconds,
		&i.DailyBudgetUsd,
		&i.Revision,
		&i.UpdatedAt,
	)
	return i, err
}
